<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; requireRole('admin');
$hospitals = $pdo->query('SELECT id, hospital_name FROM hospitals ORDER BY hospital_name')->fetchAll(PDO::FETCH_ASSOC);
if ($_SERVER['REQUEST_METHOD'] === 'POST') { if (!verifyCsrfToken($_POST['csrf_token'] ?? null)) { flash('danger', 'The form expired.'); } else { $hospitalId = filter_input(INPUT_POST, 'hospital_id', FILTER_VALIDATE_INT); $name = trim($_POST['department_name'] ?? ''); if (!$hospitalId || $name === '') { flash('danger', 'Select a hospital and enter a department name.'); } else { $insert = $pdo->prepare('INSERT INTO departments (hospital_id, department_name) VALUES (:hospital_id, :name)'); $insert->execute([':hospital_id' => $hospitalId, ':name' => $name]); logAudit('DEPARTMENT_CREATED', 'department', (int) $pdo->lastInsertId(), 'Department created by administrator.'); flash('success', 'Department added.'); redirect('departments.php'); } } }
$departments = $pdo->query('SELECT d.department_name, h.hospital_name FROM departments d JOIN hospitals h ON h.id = d.hospital_id ORDER BY h.hospital_name, d.department_name')->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Departments'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Administration</p><h1 class="h2">Departments</h1></div></div><div class="row g-4"><div class="col-lg-5"><div class="setup-card"><h2 class="h5">Add department</h2><?php if (!$hospitals): ?><p class="text-muted">Add a hospital before creating departments.</p><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><label class="form-label">Hospital</label><select class="form-select mb-3" name="hospital_id" required><option value="">Select hospital</option><?php foreach ($hospitals as $hospital): ?><option value="<?= (int) $hospital['id'] ?>"><?= e($hospital['hospital_name']) ?></option><?php endforeach; ?></select><label class="form-label">Department name</label><input class="form-control mb-3" name="department_name" required><button class="btn btn-primary">Add department</button></form><?php endif; ?></div></div><div class="col-lg-7"><div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Departments</h2><table class="table"><thead><tr><th>Department</th><th>Hospital</th></tr></thead><tbody><?php foreach ($departments as $department): ?><tr><td><?= e($department['department_name']) ?></td><td><?= e($department['hospital_name']) ?></td></tr><?php endforeach; ?><?php if (!$departments): ?><tr><td colspan="2" class="text-muted">No departments added yet.</td></tr><?php endif; ?></tbody></table></div></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>